*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:           #f5f5f7;
  --color-surface:      #ffffff;
  --color-border:       #d1d1d6;
  --color-border-focus: #0071e3;
  --color-text:         #1d1d1f;
  --color-text-muted:   #6e6e73;
  --color-primary:      #0071e3;
  --color-primary-dark: #0058b0;
  --color-primary-text: #ffffff;
  --color-radio-mark:   #0071e3;
  --color-success-bg:   #e8f5e9;
  --color-success-text: #1b5e20;
  --color-success-border:#388e3c;

  --radius-card:  16px;
  --radius-input: 10px;
  --radius-btn:   10px;

  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.08);
  --transition:  150ms ease;

  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

/* ─── Base ───────────────────────────────────────────────── */
html { font-size: 16px; }

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

/* ─── Skip link ──────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--color-primary);
  color: var(--color-primary-text);
  padding: 8px 16px;
  border-radius: var(--radius-btn);
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 16px; outline: 3px solid var(--color-border-focus); outline-offset: 2px; }

/* ─── Card ───────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  width: 100%;
  max-width: 480px;
  padding: 40px 36px 36px;
}

.card__eyebrow {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: 8px;
}

.card__title {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.25;
  margin-bottom: 6px;
}

.card__subtitle {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  margin-bottom: 32px;
}

/* ─── Form field ─────────────────────────────────────────── */
.form-field {
  margin-bottom: 28px;
}

.form-field__legend {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 16px;
  display: block;
  width: 100%;
}

/* ─── Radio group ────────────────────────────────────────── */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
  /* reset fieldset defaults */
  border: none;
  padding: 0;
  min-width: 0;
}

.radio-option {
  position: relative;
}

/* Hide native radio visually but keep it accessible */
.radio-option__input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.radio-option__label {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-input);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  user-select: none;
  font-size: 0.9375rem;
  font-weight: 500;
  overflow-wrap: anywhere;
}

.radio-option__label:hover {
  border-color: var(--color-border-focus);
  background: #f0f7ff;
}

/* Custom radio circle */
.radio-option__circle {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  background: var(--color-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background var(--transition);
}

.radio-option__circle::after {
  content: "";
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-primary-text);
  opacity: 0;
  transform: scale(0.5);
  transition: opacity var(--transition), transform var(--transition);
}

/* Checked state */
.radio-option__input:checked + .radio-option__label {
  border-color: var(--color-border-focus);
  background: #e8f2ff;
}

.radio-option__input:checked + .radio-option__label .radio-option__circle {
  border-color: var(--color-radio-mark);
  background: var(--color-radio-mark);
}

.radio-option__input:checked + .radio-option__label .radio-option__circle::after {
  opacity: 1;
  transform: scale(1);
}

/* Focus-visible ring on label */
.radio-option__input:focus-visible + .radio-option__label {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ─── Icon ───────────────────────────────────────────────── */
.radio-option__icon {
  font-size: 1.1rem;
  flex-shrink: 0;
  /* SVG/emoji inherits color via currentColor */
}

/* ─── Submit button ──────────────────────────────────────── */
.btn-submit {
  display: block;
  width: 100%;
  padding: 14px 24px;
  background: var(--color-primary);
  color: var(--color-primary-text);
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-primary-dark);
  box-shadow: 0 4px 16px rgba(0, 113, 227, 0.35);
}

.btn-submit:active { transform: scale(0.98); }

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ─── Success banner ─────────────────────────────────────── */
.success-banner {
  display: none;
  align-items: center;
  gap: 10px;
  background: var(--color-success-bg);
  color: var(--color-success-text);
  border: 1.5px solid var(--color-success-border);
  border-radius: var(--radius-input);
  padding: 14px 16px;
  font-size: 0.9375rem;
  font-weight: 500;
  margin-bottom: 20px;
}

.success-banner[aria-hidden="false"] { display: flex; }

/* ─── Reflow (320 px) ────────────────────────────────────── */
@media (max-width: 360px) {
  .card { padding: 28px 18px 24px; }
  .card__title { font-size: 1.25rem; }
}

/* ─── Forced colors ──────────────────────────────────────── */
@media (forced-colors: active) {
  .radio-option__label {
    border: 2px solid ButtonBorder;
    color: ButtonText;
  }
  .radio-option__input:checked + .radio-option__label {
    border-color: Highlight;
    background: Canvas;
  }
  .radio-option__circle {
    border-color: ButtonBorder;
    background: Canvas;
    forced-color-adjust: none;
  }
  .radio-option__input:checked + .radio-option__label .radio-option__circle {
    border-color: Highlight;
    background: Highlight;
  }
  .radio-option__circle::after { background: HighlightText; }
  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonBorder;
    forced-color-adjust: none;
  }
  .btn-submit:focus-visible { outline: 3px solid Highlight; }
  .radio-option__input:focus-visible + .radio-option__label { outline: 3px solid Highlight; }
}
